head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil00100";
scwin.otherFormObj = undefined;
scwin.pageSize = null;

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — menuDiv
// TODO Stage2: 세션 키 실환경 확인(회신 11항 · user-info 계약에 없는 키) — session.user.usrTpCd, session.user.corpUsrTpCd, session.user.exmptObjDisclsYn

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.pageSize = "" + dma_pageContext.get("pageSize") + "";
        scwin.init_rowCopy();
        scwin.init_conds();
        scwin.init_sessionFill();
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil00100.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_usrTpCd", fn: function(){ return ($c.session.getUserInfo("usrTpCd") === '3'); } }, { id: "if_menuDiv", fn: function(){ return ((dma_pageContext.get("menuDiv") ?? "") !== 'L'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_method", fn: function () { return String((dma_pageContext.get("method") ?? "")); } },
        { childId: "ipt_disclsTitle", fn: function () { return String((dma_pageContext.get("disclsTitle") ?? "")); } },
        { childId: "__rb0", fn: function () { return "전체 " + String(dma_docPage.get("total")) + "건 (" + String(dma_docPage.get("currentPage")) + "/" + String(dma_docPage.get("endListPage")) + " 페이지) "; } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

// 세션 사용자 결선 (어휘 session_attribute 2건 — gcc $c.session.getUserInfo)

/**
 * @method
 * @name init_sessionFill
 * @description 초기화 — session Fill
 * @returns {void}
 * @hidden N
 */
scwin.init_sessionFill = function () {
    const names = ["corpUsrTpCd","exmptObjDisclsYn"];
    function fill() {
        for (let i = 0; i < names.length; i++) {
            let v; try { v = $c.session.getUserInfo(names[i]); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil00100' }); v = undefined; }
            if (v === undefined || v === null || v === '') { continue; }
            const token = '${session.user.' + names[i] + '}';
            let r0 = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document); r0 = r0.body || r0; const doc = r0.ownerDocument || r0; const w = doc.createTreeWalker(r0, NodeFilter.SHOW_TEXT);
            let n; while ((n = w.nextNode())) { if (n.nodeValue.indexOf(token) >= 0) { n.nodeValue = n.nodeValue.split(token).join(v); } }
            const ins = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelectorAll('input, textarea');
            for (let j = 0; j < ins.length; j++) { if (ins[j].value && ins[j].value.indexOf(token) >= 0) { ins[j].value = ins[j].value.split(token).join(v); } }
        }
    }
    fill();
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_submit). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_goWrite_next();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_52_onclick
 * @description img_52 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_52_onclick = function(e){
    try {
        fn_ViewManualKeyWord(0200000015)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00100.img_52_onclick' }); }
};

/**
 * @method
 * @name cal_searchBeginDd_onblur
 * @description cal_searchBeginDd 포커스 이탈 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cal_searchBeginDd_onblur = async function(e){
    try {
        await (async (c) => { const raw = String((c && c.getValue) ? (c.getValue() ?? "") : ""); if (raw.length === 0) { return true; } const v = raw.split("-").join("").split("/").join(""); if (c && c.setValue) { c.setValue(v); } const lbl = ""; const lp = lbl ? (lbl + ": ") : ""; if (v.length !== 8) { await $c.win.alert(lp + "날짜는 8 자리 YYYYMMDD 형식입니다."); if (c && c.focus) { c.focus(); } return false; } let digits = true; for (let i = 0; i < v.length; i++) { const ch = v.charAt(i); if (ch < "0" || ch > "9") { digits = false; break; } } if (!digits) { await $c.win.alert(lp + "숫자만 입력가능합니다."); if (c && c.focus) { c.focus(); } return false; } const mm = Number(v.substring(4, 6)); if (mm > 12 || mm < 1) { await $c.win.alert(lp + "달은 1 에서 12 사이여야 합니다."); if (c && c.focus) { c.focus(); } return false; } if (!$c.date.checkCalendarFormat(c, "yyyyMMdd", { clearOnInvalid: false })) { await $c.win.alert(lp + " 존재하지 않는 날짜입니다."); if (c && c.focus) { c.focus(); } return false; } return true; })($c.util.getComponent("cal_searchBeginDd"));

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil00100.cal_searchBeginDd_onblur' }); }
};

/**
 * @method
 * @name cal_searchEndDd_onblur
 * @description cal_searchEndDd 포커스 이탈 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cal_searchEndDd_onblur = async function(e){
    try {
        await (async (c) => { const raw = String((c && c.getValue) ? (c.getValue() ?? "") : ""); if (raw.length === 0) { return true; } const v = raw.split("-").join("").split("/").join(""); if (c && c.setValue) { c.setValue(v); } const lbl = ""; const lp = lbl ? (lbl + ": ") : ""; if (v.length !== 8) { await $c.win.alert(lp + "날짜는 8 자리 YYYYMMDD 형식입니다."); if (c && c.focus) { c.focus(); } return false; } let digits = true; for (let i = 0; i < v.length; i++) { const ch = v.charAt(i); if (ch < "0" || ch > "9") { digits = false; break; } } if (!digits) { await $c.win.alert(lp + "숫자만 입력가능합니다."); if (c && c.focus) { c.focus(); } return false; } const mm = Number(v.substring(4, 6)); if (mm > 12 || mm < 1) { await $c.win.alert(lp + "달은 1 에서 12 사이여야 합니다."); if (c && c.focus) { c.focus(); } return false; } if (!$c.date.checkCalendarFormat(c, "yyyyMMdd", { clearOnInvalid: false })) { await $c.win.alert(lp + " 존재하지 않는 날짜입니다."); if (c && c.focus) { c.focus(); } return false; } return true; })($c.util.getComponent("cal_searchEndDd"));

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil00100.cal_searchEndDd_onblur' }); }
};

/**
 * @method
 * @name img_92_onclick
 * @description img_92 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_92_onclick = async function(e){
    try {
        await scwin.searchList()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00100.img_92_onclick' }); }
};

/**
 * @method
 * @name slc_pageSize_onchange
 * @description slc_pageSize 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.slc_pageSize_onchange = async function(e){
    try {
        scwin.initPageIndex();await scwin.searchList()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00100.slc_pageSize_onchange' }); }
};

/**
 * @method
 * @name grd_docPageList_oncellclick
 * @description grd_docPageList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_docPageList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_docPageList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_docPageList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; } /* 수동 전환 필요: fn_viewOtherForm (인자 미해석) · document.getElementById('${doc.acptNo}'+'_0_otherForm').style.display = 'none'; (EL 미해석) · fn_goWrite( '${doc.acptNo}', '${doc.formCd}', '${doc.formVer}' , '${doc.beforeFormVer}' , '${doc.beforeEngFormVer}', '${doc.oldFormVerUseYn}', '${doc.langTpCd}', '${doc.formUpclssCd}' ,'${doc.rsnClssCd}','${doc.modOrgnDisclsAcptNo}','${doc.inqOrgnDisclsAcptNo}','${doc.engOrgnDisclsAcptNo}','${doc.modAddSeq}','${doc.applFormYn}' ,'${doc.ldMktTpCd }','${doc.disclsAcptTpCd}','${doc.subcomDisclsYn }','${doc.disclsObjCorpIsurCd }','${doc.disclsObjCorpIsurNm }','${doc.disclsObjCorpFssUnqNo }','${doc.disclsObjRepIsuSrtCd }','${doc.disclsObjIsuCd }','${fn:replace(doc.comEngAbbrv, '\'', '\\'') }','${doc.exmptObjDisclsYn }','${doc.reqObjAptDocYn}','${doc.disclsObjRepIsuSrtNm}' ); (EL 미해석) · fn_goWrite( '${doc.acptNo}', '${doc.formCd}', '${doc.formVer}', '${doc.currFormVer}', '${doc.currEngFormVer}', '${doc.oldFormVerUseYn}', '${doc.langTpCd}', '${doc.formUpclssCd}' ,'${doc.rsnClssCd}','${doc.modOrgnDisclsAcptNo}','${doc.inqOrgnDisclsAcptNo}','${doc.engOrgnDisclsAcptNo}','${doc.modAddSeq}','${doc.applFormYn}' ,'${doc.ldMktTpCd }','${doc.disclsAcptTpCd}','${doc.subcomDisclsYn }','${doc.disclsObjCorpIsurCd }','${doc.disclsObjCorpIsurNm }','${doc.disclsObjCorpFssUnqNo }','${doc.disclsObjRepIsuSrtCd }','${doc.disclsObjIsuCd }','${fn:replace(doc.comEngAbbrv, '\'', '\\'') }','${doc.exmptObjDisclsYn }','${doc.reqObjAptDocYn}' ,'${doc.disclsObjRepIsuSrtNm}'); (EL 미해석) · fn_goWrite( '${doc.acptNo}', '${doc.formCd}', '${doc.formVer}', '${doc.currFormVer}', '${doc.currEngFormVer}', '${doc.oldFormVerUseYn}', '${doc.langTpCd}', '${doc.formUpclssCd}' ,'${doc.rsnClssCd}','${doc.modOrgnDisclsAcptNo}','${doc.inqOrgnDisclsAcptNo}','${doc.engOrgnDisclsAcptNo}','${doc.modAddSeq}','${doc.applFormYn}' ,'${doc.ldMktTpCd }','${doc.disclsAcptTpCd}','${doc.subcomDisclsYn }','${doc.disclsObjCorpIsurCd }','${doc.disclsObjCorpIsurNm }','${doc.disclsObjCorpFssUnqNo }','${doc.disclsObjRepIsuSrtCd }','${doc.disclsObjIsuCd }','${fn:replace(doc.comEngAbbrv, '\'', '\\'') }','${doc.exmptObjDisclsYn }' ,'${doc.reqObjAptDocYn}','${doc.disclsObjRepIsuSrtNm}'); (EL 미해석) */

    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_docPageList.oncellclick' });
    }
};

/**
 * @method
 * @name krxpage_pagenavigator_197_onclick
 * @description krxpage_pagenavigator_197 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_197_onclick = async function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_goWriteNextReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_197.page' }); } await scwin.tx_fn_goWrite_next(); };

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_searchList
 * @description search List 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_searchList = async function () {
    const sbmOptions = {
        id: "tx_fn_searchList",
        method: "post",
        action: "",
        ref: "dma_goWriteNextReq",
        target: "dlt_docPageList=body",
        isProcessMsg: false
    };
    return await $c.sbm.executeDynamic(sbmOptions);
};

/**
 * @method
 * @name tx_fn_goWrite_next
 * @description go Write next 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_goWrite_next = async function () {
    const sbmOptions = {
        id: "tx_fn_goWrite_next",
        method: "post",
        action: "/submission/disclosure.do?method=searchChangeDocumentDetail",
        ref: "dma_goWriteNextReq",
        target: "dlt_docPageList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    const rj = res && res.responseJSON;
    const tot = rj && (rj["total"] != null ? rj["total"] : (rj.body && rj.body["total"]));
    if (tot != null && tot !== "") {
        $c.util.getComponent("krxpage_pagenavigator_197").setCount(Math.ceil(Number(tot) / 10));
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initPageIndex
 * @description init Page Index 처리
 * @returns {void}
 * @hidden N
 */
scwin.initPageIndex = function () {
    $c.util.getComponent('dma_goWriteNextReq').set('pageIndex', "1");
};

/**
 * @method
 * @name grd_docPageList_fmt_formKorNm
 * @description grd doc Page List fmt form Kor Nm 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_docPageList_fmt_formKorNm = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_docPageList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "oldFormVerUseYn") ?? '') : '');
        if (v === 'Y') { return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + String((dl && dl.getCellData ? dl.getCellData(r, "formKorNm") : '') ?? '') + '</a>'; }
        return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + String((dl && dl.getCellData ? dl.getCellData(r, "formKorNm") : '') ?? '') + '</a>';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_docPageList.formKorNm" }); return String(data ?? ''); }
};

/**
 * @method
 * @name grd_docPageList_fmt_column5
 * @description grd doc Page List fmt column5 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_docPageList_fmt_column5 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_docPageList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "disclsAcptTpCd") ?? '') : '');
        if (v === 'F') { return "최초"; }
        if (v === 'M') { return "정정"; }
        if (v === 'A') { return "첨부추가"; }
        if (v === 'U') { return "첨부정정"; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_docPageList.column5" }); return String(data ?? ''); }
};

/**
 * @method
 * @name grd_docPageList_fmt_column6
 * @description grd doc Page List fmt column6 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_docPageList_fmt_column6 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_docPageList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "formUpclssCd") ?? '') : '');
        if (v === '09') { return "ELW"; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_docPageList.column6" }); return String(data ?? ''); }
};

/**
 * @method
 * @name grd_docPageList_fmt_column7
 * @description grd doc Page List fmt column7 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_docPageList_fmt_column7 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_docPageList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "listFormYn") ?? '') : '');
        if (v === 'Y') { return "상장"; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_docPageList.column7" }); return String(data ?? ''); }
};

/**
 * @method
 * @name searchList
 * @description search List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchList = async function () {
    const frm = (document.searchForm || { elements: [] });
    if ($c.util.getComponent('cal_searchBeginDd').getValue()> $c.util.getComponent('cal_searchEndDd').getValue()) {
        await $c.win.alert('시작일이 종료일보다 이후 일자 입니다.');
        return;
    }
    await scwin.tx_fn_searchList();
};

/**
 * @method
 * @name goWriteNext
 * @description go Write Next 처리
 * @param {*} acptNo acptNo
 * @param {String} formCd formCd
 * @param {*} formVer formVer
 * @param {*} currFormVer currFormVer
 * @param {*} currEngFormVer currEngFormVer
 * @param {String} oldFormVerUseYn oldFormVerUseYn
 * @param {String} langTpCd langTpCd
 * @param {String} formUpclssCd formUpclssCd
 * @param {String} rsnClssCd rsnClssCd
 * @param {*} modOrgnDisclsAcptNo modOrgnDisclsAcptNo
 * @param {*} inqOrgnDisclsAcptNo inqOrgnDisclsAcptNo
 * @param {*} engOrgnDisclsAcptNo engOrgnDisclsAcptNo
 * @param {*} modAddSeq modAddSeq
 * @param {String} applFormYn applFormYn
 * @param {String} ldMktTpCd ldMktTpCd
 * @param {String} disclsAcptTpCd disclsAcptTpCd
 * @param {String} subcomDisclsYn subcomDisclsYn
