            $c.util.getComponent('dma_goWriteNextReq').set('disclsMaindocFormVer', currFormVer);
            $c.util.getComponent('dma_goWriteNextReq').set('formVer', currFormVer);
        } else {
            $c.util.getComponent('dma_goWriteNextReq').set('disclsMaindocFormVer', formVer);
            $c.util.getComponent('dma_goWriteNextReq').set('formVer', formVer);
        }
    } else {
        if (formVer !== currEngFormVer) {
            await $c.win.alert('* 서식버전이 변경되어 더이상 유효하지 않습니다. \n* 새문서로 작성하여 제출하시기 바랍니다.');
            $c.util.getComponent('dma_goWriteNextReq').set('disclsMaindocFormVer', currEngFormVer);
            $c.util.getComponent('dma_goWriteNextReq').set('formVer', currEngFormVer);
        } else {
            $c.util.getComponent('dma_goWriteNextReq').set('disclsMaindocFormVer', formVer);
            $c.util.getComponent('dma_goWriteNextReq').set('formVer', formVer);
        }
    }
    $c.util.getComponent('dma_goWriteNextReq').set('tgtIsurCd', disclsObjCorpIsurCd);
