    $c.util.getComponent('dma_goWriteNextReq').set('modOrgnDisclsAcptNo', modOrgnDisclsAcptNo);
    if (disclsAcptTpCd === 'A') {
        $c.util.getComponent('dma_goWriteNextReq').set('modOrgnDisclsAcptNo', addOrgnDisclsAcptNo);
    }
    $c.util.getComponent('dma_goWriteNextReq').set('addOrgnDisclsAcptNo', acptNo);
    $c.util.getComponent('dma_goWriteNextReq').set('inqOrgnDisclsAcptNo', inqOrgnDisclsAcptNo);
    $c.util.getComponent('dma_goWriteNextReq').set('engOrgnDisclsAcptNo', engOrgnDisclsAcptNo);
    $c.util.getComponent('dma_goWriteNextReq').set('modAddSeq', modAddSeq);
    if (acptNo !== inqOrgnDisclsAcptNo && inqOrgnDisclsAcptNo !== '') {
        $c.util.getComponent('dma_goWriteNextReq').set('disclsModAddTpCd', 'Q');
    }
    let acptApplTpCd = 'D';
    if (applFormYn === 'Y') {
        acptApplTpCd = 'L';
    }
    $c.util.getComponent('dma_goWriteNextReq').set('acptApplTpCd', acptApplTpCd);
    let engFormYn = 'N';
