/**
 * @method
 * @name viewOtherForm
 * @description view Other Form 처리
 * @param {String} divId divId
 * @param {String} langTpCd langTpCd
 * @returns {void}
 * @hidden N
 */
scwin.viewOtherForm = function (divId, langTpCd) {
    if (scwin.otherFormObj != null && scwin.otherFormObj !== 'undefined') {
        scwin.otherFormObj.style.display = 'none';
    }
    if ($c.util.getComponent(divId + '_otherForm').getStyle('display') === 'none') {
        ($c.util.getComponent(divId + '_otherForm') && $c.util.getComponent(divId + '_otherForm').show ? $c.util.getComponent(divId + '_otherForm').show() : console.warn('[sdd] show 대상 미해결: ' + divId + '_otherForm'));
    } else {
        ($c.util.getComponent(divId + '_otherForm') && $c.util.getComponent(divId + '_otherForm').hide ? $c.util.getComponent(divId + '_otherForm').hide() : console.warn('[sdd] hide 대상 미해결: ' + divId + '_otherForm'));
    }
    scwin.otherFormObj = $c.util.getComponent(divId + '_otherForm');
};
